package com.cryptostrategy.platform.backtesting.internal;
import static org.junit.jupiter.api.Assertions.*;import com.cryptostrategy.platform.strategy.api.Strategy;import com.cryptostrategy.platform.strategy.api.model.*;import java.util.Map;import java.util.concurrent.atomic.AtomicInteger;import org.junit.jupiter.api.Test;
class StrategyExecutionInteropTest{@Test void suppliesOnlyClosedBoundedWindowAtCurrentEvaluationTime(){BacktestTestFixture f=new BacktestTestFixture();AtomicInteger largest=new AtomicInteger();Strategy strategy=context->{largest.set(Math.max(largest.get(),context.candles().size()));assertTrue(context.candles().stream().allMatch(c->c.closed()));assertEquals(context.candles().getLast().closeTime(),context.evaluationTime());return new StrategyDecision(StrategySignal.HOLD,context.evaluationTime(),f.reference,"HOLD","test",Map.of());};StrategyExecutionSession session=new StrategyExecutionSession(f.dataset,strategy,2);f.members.forEach(m->session.evaluate(m.candle().candle()));assertEquals(2,largest.get());assertEquals(2,session.retainedCandleCount());}}
